{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Tetrabenazine showed oral bioavailability of 8.5% in a patient after a single 50 mg fed dose, well below the 20% threshold; direct human systemic availability measurement with high transfer supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Felodipine absolute oral bioavailability was 17.0% in cirrhotic patients and 12–16% in fasted volunteers, below 20%; direct human IV-comparison data with high transfer supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Tegaserod absolute oral bioavailability is approximately 10% in fasting humans, below 20%; direct human data with high transfer supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Delmopinol has very low oral bioavailability in humans after swallowing, consistent with a locally acting oral agent; supports low F for a GI-targeted lipophilic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Colesevelam has negligible systemic bioavailability (<0.04%) in humans, demonstrating that non-absorbed GI-acting agents can have extremely low F; supports low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Oseltamivir carboxylate has ~79% absolute oral bioavailability in healthy volunteers, showing that some ester/amide drugs are well absorbed; however, lower transferability and structural differences limit its weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "A long-chain ester/amide analogue (DVAS) had average 60% oral bioavailability in healthy volunteers, a structurally closer high-F example; low transferability tempers its contradiction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a highly lipophilic GI-acting lipase inhibitor. Multiple high-transfer human absolute bioavailability measurements for tetrabenazine, felodipine, tegaserod, delmopinol, and colesevelam are all below 20%, often very low, supporting low oral bioavailability. Contradictory high-F ester/amide analogues have lower transferability and lack the beta-lactone/local-action features. Therefore predict low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat in the provided evidence.",
    "No data on intestinal hydrolysis or lactone stability for the query.",
    "No formulation-specific or food-effect data for the query.",
    "Contradictory high-F analogues have lower transfer scores and structural differences."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

